export interface User {
  id: string;
  name: string;
  email: string;
  avatar?: string;
  role: 'admin' | 'member' | 'guest';
  skills: string[];
  joinDate: Date;
  isActive: boolean;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  startDate: Date;
  endDate: Date;
  status: 'planning' | 'active' | 'completed' | 'suspended';
  goals: string[];
  kpis: KPI[];
  teamMembers: ProjectMember[];
  createdBy: string;
  createdAt: Date;
}

export interface Task {
  id: string;
  projectId: string;
  title: string;
  description: string;
  assignee: string;
  priority: 'high' | 'medium' | 'low';
  status: 'todo' | 'in_progress' | 'review' | 'done';
  estimatedHours: number;
  actualHours?: number;
  dueDate: Date;
  dependencies: string[];
  tags: string[];
  createdAt: Date;
  completedAt?: Date;
}

export interface Evaluation {
  id: string;
  userId: string;
  targetType: 'task' | 'project' | 'daily';
  targetId: string;
  selfScore: number;
  peerScores: PeerScore[];
  autoScore?: number;
  comments: string;
  improvements: string[];
  learnings: string[];
  evaluatedAt: Date;
}

export interface Action {
  id: string;
  title: string;
  description: string;
  assignee: string;
  dueDate: Date;
  status: 'planned' | 'in_progress' | 'completed';
  priority: 'high' | 'medium' | 'low';
  relatedEvaluation: string;
  impact: 'high' | 'medium' | 'low';
  effort: 'high' | 'medium' | 'low';
  createdAt: Date;
  completedAt?: Date;
}

/**
 * プロジェクト進捗率を計算
 * @param completedTasks - 完了タスク数
 * @param totalTasks - 全タスク数
 * @returns 進捗率（0-1）
 */
export function calculateProjectProgress(
  completedTasks: number,
  totalTasks: number
): number {
  if (totalTasks === 0) return 0;
  return Math.min(completedTasks / totalTasks, 1);
}

/**
 * 技術成長度を計算
 * @param acquiredSkills - 習得技術数
 * @param averageScore - 平均評価スコア
 * @returns 技術成長度
 */
export function calculateTechnicalGrowth(
  acquiredSkills: number,
  averageScore: number
): number {
  return acquiredSkills * averageScore;
}

/**
 * 実行力を計算
 * @param completionRate - 計画達成率
 * @param onTimeRate - 納期遵守率
 * @returns 実行力（0-100）
 */
export function calculateExecutionPower(
  completionRate: number,
  onTimeRate: number
): number {
  return completionRate * onTimeRate * 100;
}

/**
 * タスクの優先度を自動判定
 * @param task - タスク情報
 * @returns 自動判定された優先度
 */
export function autoAssignPriority(task: Task): Priority {
  const daysUntilDue = differenceInDays(task.dueDate, new Date());

  // 期限が3日以内 → 高
  if (daysUntilDue <= 3) {
    return 'high';
  }

  // 依存タスクがブロック中 → 高
  if (task.dependencies.some(isBlocking)) {
    return 'high';
  }

  // 影響度が高い → 中以上
  if (task.impact === 'high') {
    return daysUntilDue <= 7 ? 'high' : 'medium';
  }

  return 'medium';
}
